		int a4 = jvalue["Feuille7"][0]["Col2"].as<int>();
		REQUIRE(a4 == 23);
		int a5 = jvalue["Feuille7"][1]["Col2"].as<int>();
		REQUIRE(a5 == 46);
		REQUIRE(check_schema_type(jschema, table, "Col2", "integer"));
		REQUIRE(check_schema_description(jschema, table, "Col2", "Col2"));
